http {
    limit_req_zone $binary_remote_addr zone=general:10m rate=10r/s;
    server {
        listen 80;
        server_name www.example.com;
        root /var/www/site;
        location / {
            limit_req zone=general burst=20 nodelay;
            try_files $uri $uri/ =404;
        }
    }
}

http {
    limit_req_zone $binary_remote_addr zone=web:10m rate=5r/s;
    limit_req_status 429;
    limit_req_log_level warn;
    server {
        listen 80;
        server_name www.news.example;
        root /var/www/news;
        location / {
            limit_req zone=web burst=10;
            try_files $uri $uri/ =404;
        }
    }
}

http {
    limit_req_zone $binary_remote_addr zone=login:10m rate=1r/s;
    server {
        listen 80;
        server_name www.blog.example;
        root /var/www/blog;
        location = /wp-login.php {
            limit_req zone=login burst=5 delay=3;
            fastcgi_pass 127.0.0.1:9000;
            fastcgi_param SCRIPT_FILENAME $document_root$fastcgi_script_name;
            include fastcgi_params;
        }
    }
}

http {
    limit_conn_zone $binary_remote_addr zone=conn:10m;
    server {
        listen 80;
        server_name filesrv.example.com;
        root /var/www/filesrv;
        limit_conn conn 50;
        location / {
            try_files $uri $uri/ =404;
        }
    }
}

http {
    limit_req_zone $binary_remote_addr zone=api:10m rate=30r/s;
    limit_conn_zone $binary_remote_addr zone=api_conn:10m;
    limit_req_status 429;
    server {
        listen 80;
        server_name api.example.com;
        location /api/ {
            limit_req zone=api burst=60 nodelay;
            limit_conn api_conn 30;
            proxy_pass http://127.0.0.1:8080;
            proxy_set_header Host $host;
        }
    }
}

geo $limit {
    default 1;
    10.10.0.0/24 0;
}
