map $binary_remote_addr $subnet24 {
    "~^(?P<d1>\d+)\.(?P<d2>\d+)\.(?P<d3>\d+)\.\d+$" $d1.$d2.$d3;
}
http {
    limit_req_zone $subnet24 zone=by24:20m rate=100r/s;
    server {
        listen 80;
        server_name www.forum.example;
        location / {
            limit_req zone=by24 burst=200;
            root /var/www/forum;
            try_files $uri $uri/ =404;
        }
    }
}

http {
    limit_req_zone $binary_remote_addr zone=shop:10m rate=10r/s;
    limit_req_status 429;
    server {
        listen 80;
        server_name shop.example.com;
        root /var/www/shop;
        error_page 429 /429.html;
        location = /429.html {
            internal;
        }
        location / {
            limit_req zone=shop burst=30 nodelay;
            try_files $uri $uri/ =404;
        }
    }
}

